275	   * client's own state with the server's hash wherever one is due, before any snapshot replaces it.
276	   */
277	  private fold(): void {
278	    for (;;) {
279	      this.runCheck(this.confirmedThrough);
280	      const next = this.confirmedThrough + 1;
281	      if (next > this.head || !samePair(this.used.get(next), this.confirmed.get(next))) break;
282	      this.confirmedThrough = next;
283	    }
284	    this.prune();
285	  }
286	
287	  private runCheck(frame: number): void {
288	    const check = this.checks.get(frame);
289	    const own = this.states.get(frame);
290	    if (check === undefined || own === undefined) return;
291	    this.checks.delete(frame);
292	    this.stats.hashChecks++;
293	    if (hashState(own) === check.hash) return;
294	    this.stats.desyncs++;
295	    if (check.snapshot === undefined) return;
296	    // The server's state is the authority: restart from it and predict forward again.
297	    this.states.set(frame, restoreDuel(this.config, check.snapshot));
298	    this.stats.snapshotRestores++;
299	    this.replayFrom(frame);
300	  }
301	
302	  /** Discards the timeline and restarts from a server snapshot at `frame`, keeping the local inputs. */
303	  private restartFrom(frame: number, snapshot: unknown, lastPair: readonly [number, number] | undefined): void {
304	    const restored = restoreDuel(this.config, snapshot);
305	    const previousHead = this.head;
306	    this.states.clear();
307	    this.used.clear();
308	    // Confirmed inputs after the snapshot stay only while they follow it without a hole.
309	    let next = frame + 1;
310	    while (this.confirmed.has(next)) next++;
311	    for (const key of [...this.confirmed.keys()]) if (key <= frame || key >= next) this.confirmed.delete(key);
312	    for (const key of [...this.checks.keys()]) if (key <= frame) this.checks.delete(key);
313	    this.states.set(frame, restored);
314	    this.head = frame;
315	    this.confirmedThrough = frame;
316	    this.receivedThrough = next - 1;
317	    if (lastPair !== undefined) this.lastConfirmed = [sanitizeDuelInput(lastPair[0]), sanitizeDuelInput(lastPair[1])];
318	    this.awaitingSnapshot = false;
319	    this.stats.snapshotRestores++;
320	    const target = Math.min(previousHead, frame + this.historyFrames);
321	    const stepped = this.stepTo(target);
322	    this.stats.replayedFrames += stepped;
323	    this.stats.deepestReplay = Math.max(this.stats.deepestReplay, stepped);
324	  }
325	
326	  private prune(): void {
327	    const keepFrom = Math.min(this.confirmedThrough, this.head - this.historyFrames);
328	    for (const map of [this.states, this.used] as const) for (const key of map.keys()) if (key < keepFrom) map.delete(key);
329	    const inputsFrom = this.confirmedThrough - this.historyFrames;
330	    for (const map of [this.confirmed, this.local] as const) for (const key of map.keys()) if (key < inputsFrom) map.delete(key);
331	    for (const key of this.checks.keys()) if (key < inputsFrom) this.checks.delete(key);
332	    this.feed.prune(inputsFrom);
333	  }
334	}
