1	import { matchMaker } from "colyseus";
2	import { afterAll, beforeAll, describe, expect, it } from "vitest";
3	import { DuelRoom, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
4	import { duelInput as I } from "@pirate-sea-race/simulation/duel";
5	import { MAX_INPUT_DELAY, MIN_INPUT_DELAY } from "@pirate-sea-race/simulation/netcode";
6	import { HeadlessDuelClient, ImpairmentProxy, logFromBundles, replayRecordedDuel, type DuelScript, type Impairment } from "@pirate-sea-race/test-tools";
7	
8	/**
9	 * The impairment harness (§19 "Network and performance targets"): two headless duel clients, running the same
10	 * rollback core as the browser, fight a scripted duel through a proxy that delays, jitters and loses messages the
11	 * way a WebSocket over TCP suffers them. Each scenario must show:
12	 *
13	 * - zero desyncs: at every bundle's frame (a snapshot or a hash every 50 ms) each client hashes its own simulated
14	 *   state, before restoring anything, and compares it with the server's;
15	 * - zero input messages dropped by the server's rate cap;
16	 * - corrections within the threshold: at most one per change of the opponent's input the server applied, plus one
17	 *   per own input the server had to substitute, and never more than CORRECTIONS_PER_SECOND on average.
18	 *
19	 * The counts are printed and attached to the test as annotations.
20	 */
21	const CORRECTIONS_PER_SECOND = 8;
22	/** Frames of scripted play (eight seconds); both clients must then confirm SETTLE_FRAMES more. */
23	const PLAY_FRAMES = 480;
24	const SETTLE_FRAMES = 60;
25	
26	const R = I("right");
27	const L = I("left");
28	const D = I("down");
29	const U = I("up");
30	const J = I("light");
31	const K = I("heavy");
32	
33	/**
34	 * Player one walks in, then cycles through a tapped jab, a held heavy, a throw pressed with rollover (K a frame after
35	 * J), backing off, a low sweep, and a jab timed to trade with player two's.
36	 */
37	const attacker: DuelScript = (frame) => {
38	  if (frame < 40) return R;
39	  const beat = (frame - 40) % 180;
40	  if (beat === 10) return J;
41	  if (beat >= 30 && beat < 34) return K;
42	  if (beat === 60) return J;
43	  if (beat > 60 && beat < 65) return J | K;
44	  if (beat >= 100 && beat < 120) return L;
