1	import { performance } from "node:perf_hooks";
2	import { Client, type Room } from "@colyseus/sdk";
3	import {
4	  DUEL_ROOM,
5	  duelFrameBundleSchema,
6	  DuelMessageType,
7	  duelProbeSchema,
8	  normalizeMatchCode,
9	  PROTOCOL_VERSION,
10	  type DuelFrameBundle,
11	  type DuelPracticeMessage,
12	  type DuelProbeReply,
13	  type DuelRoomPhase,
14	  type DummyBehaviour,
15	} from "@pirate-sea-race/protocol";
16	import type { DuelRoomStateSchema } from "@pirate-sea-race/server/schema";
17	import { createDuelState, defaultDuelConfig, type DuelState, type PlayerIndex } from "@pirate-sea-race/simulation/duel";
18	import { DuelClientSession, type DuelSessionStats } from "@pirate-sea-race/simulation/netcode";
19	import { newCreateToken, sleep } from "./headlessClient.js";
20	
21	/**
22	 * What a scripted player holds at each of its client frames (the frame it is on, before the input delay), like keys
23	 * held down: `script(frame)` is called once per tick with the client's current frame.
24	 */
25	export type DuelScript = (clientFrame: number, session: DuelClientSession) => number;
26	
27	export interface HeadlessDuelOptions {
28	  readonly protocolVersion?: number;
29	  /** How often the client ticks, in milliseconds (the browser ticks about every 4 ms). */
30	  readonly tickMs?: number;
31	}
32	
33	/**
34	 * A browserless duel player on the real Colyseus SDK that runs the same `DuelClientSession` as the browser: it answers
35	 * the server's round-trip probes, feeds frame bundles to the rollback core, and ticks the session every few
36	 * milliseconds with the input its script holds, sending what the session returns. It records every bundle, so a test
37	 * can replay what the server confirmed.
38	 */
39	export class HeadlessDuelClient {
40	  private session: DuelClientSession | undefined;
41	  private script: DuelScript = () => 0;
42	  private readonly timer: NodeJS.Timeout;
43	  private open = true;
44	  private dropped = false;
45	  readonly bundles: DuelFrameBundle[] = [];
46	
47	  private constructor(
48	    readonly room: Room<unknown, DuelRoomStateSchema>,
49	    options: HeadlessDuelOptions,
50	  ) {
51	    room.onMessage(DuelMessageType.Probe, (message: unknown) => {
52	      const probe = duelProbeSchema.parse(message);
53	      room.send(DuelMessageType.Probe, { id: probe.id } satisfies DuelProbeReply);
54	      this.ensureSession()?.receiveProbe(probe, performance.now());
55	    });
56	    room.onMessage(DuelMessageType.Frames, (message: unknown) => {
57	      const bundle = duelFrameBundleSchema.parse(message);
58	      this.bundles.push(bundle);
59	      this.ensureSession()?.receiveBundle(bundle, performance.now());
60	    });
61	    room.onDrop(() => {
62	      this.dropped = true;
63	    });
64	    room.onReconnect(() => {
65	      this.dropped = false;
66	    });
67	    room.onLeave(() => {
68	      this.open = false;
69	      clearInterval(this.timer);
70	    });
71	    this.timer = setInterval(() => this.tick(), options.tickMs ?? 4);
72	  }
73	
74	  /** Creates a duel (or a practice duel against the dummy) on the server at `endpoint`. */
75	  static async create(endpoint: string, options: HeadlessDuelOptions & { readonly practice?: boolean } = {}): Promise<HeadlessDuelClient> {
76	    const room = await new Client(endpoint).create<DuelRoomStateSchema>(DUEL_ROOM, {
77	      protocolVersion: options.protocolVersion ?? PROTOCOL_VERSION,
78	      createToken: newCreateToken(),
79	      ...(options.practice === true ? { practice: true } : {}),
80	    });
81	    const client = new HeadlessDuelClient(room, options);
82	    await client.waitFor(() => client.code !== "" && client.slot !== undefined);
83	    return client;
84	  }
85	
86	  /** Joins the duel with `code` (any case). */
87	  static async join(endpoint: string, code: string, options: HeadlessDuelOptions = {}): Promise<HeadlessDuelClient> {
88	    const room = await new Client(endpoint).join<DuelRoomStateSchema>(DUEL_ROOM, {
89	      protocolVersion: options.protocolVersion ?? PROTOCOL_VERSION,
90	      code: normalizeMatchCode(code),
91	    });
92	    const client = new HeadlessDuelClient(room, options);
93	    await client.waitFor(() => client.slot !== undefined);
94	    return client;
95	  }
96	
97	  get sessionId(): string {
98	    return this.room.sessionId;
99	  }
100	
101	  get code(): string {
102	    return this.room.state?.code ?? "";
103	  }
104	
105	  get phase(): DuelRoomPhase | "" {
106	    return (this.room.state?.phase ?? "") as DuelRoomPhase | "";
107	  }
108	
109	  get connected(): boolean {
110	    return this.open && !this.dropped;
111	  }
112	
113	  /** This player's index: 0 for the creator, 1 for the joiner. */
114	  get slot(): PlayerIndex | undefined {
115	    const seat = this.room.state?.seats?.find((entry) => entry.sessionId === this.room.sessionId);
116	    return seat === undefined ? undefined : (seat.slot as PlayerIndex);
117	  }
118	
119	  /** The rollback session, once the room's seed and this client's seat are known. */
120	  get duel(): DuelClientSession | undefined {
121	    return this.ensureSession();
122	  }
123	
124	  get stats(): DuelSessionStats | undefined {
125	    return this.session?.stats;
126	  }
127	
128	  /** The newest state stepped from the server's confirmed inputs. */
129	  get confirmedState(): DuelState | undefined {
130	    return this.session?.confirmedState;
131	  }
132	
133	  /** Holds inputs from now on according to `script`. */
134	  play(script: DuelScript): void {
135	    this.script = script;
136	  }
137	
138	  /** Practice rooms: switch the dummy between idle and guarding. */
139	  setDummy(dummy: DummyBehaviour): void {
140	    this.room.send(DuelMessageType.Practice, { dummy } satisfies DuelPracticeMessage);
141	  }
142	
143	  /** Sends anything at all on the duel's input channel, for tests of the server's validation. */
144	  sendRaw(type: string, payload: unknown): void {
145	    this.room.send(type, payload);
146	  }
147	
148	  /** Resolves once `predicate` holds; rejects after `timeoutMs`. */
149	  async waitFor(predicate: () => boolean, timeoutMs = 10_000): Promise<void> {
150	    const deadline = Date.now() + timeoutMs;
151	    while (!predicate()) {
152	      if (Date.now() > deadline) throw new Error(`condition not met within ${timeoutMs} ms`);
153	      await sleep(10);
154	    }
155	  }
156	
157	  /** Resolves once the duel's confirmed frame reaches `frame`. */
158	  async waitForConfirmed(frame: number, timeoutMs = 20_000): Promise<void> {
159	    await this.waitFor(() => (this.session?.rollback.confirmedFrame ?? -1) >= frame, timeoutMs);
160	  }
161	
162	  /** Leaves the duel; a client whose connection is down stops reconnecting and closes instead. */
163	  async leave(): Promise<void> {
164	    clearInterval(this.timer);
165	    if (!this.open) return;
166	    this.room.reconnection.enabled = false;
167	    if (this.room.connection?.isOpen !== true) {
168	      this.open = false;
169	      return;
170	    }
171	    await Promise.race([this.room.leave(true).catch(() => undefined), sleep(2000)]);
172	  }
173	
174	  private ensureSession(): DuelClientSession | undefined {
175	    if (this.session !== undefined) return this.session;
176	    const state = this.room.state;
