    const rollback = new DuelRollback(config, 0, nearKo(40));
    rollback.setLocalInput(1, J);
    rollback.stepTo(40);
    const predicted = rollback.drainEvents();
    const kos = predicted.filter((event) => event.result !== null);
    expect(kos).toHaveLength(1);
