      }
      expect(session.stats.corrections).toBe(0);
      expect(session.stats.desyncs).toBe(0);
      expect(hashState(session.confirmedState)).toBe(hashState(authority.state));
      expect(authority.stats.received[0]).toBe(60);
      // J alone would have been a jab (45); the chord became the throw, which landed after the escape window.
      expect(authority.state.fighters[1].health).toBe(1000 - 120);
    }
  });

  it("catches up at most four frames a tick, and resyncs from the latest snapshot after a long gap", () => {
    const { session, at, edge, tick } = sessionRig();
    tick(at(1), 0);
    tick(at(1 + 3 * CATCH_UP_FRAMES), 0);
    expect(session.frame).toBe(1 + CATCH_UP_FRAMES);
    const authority = new DuelAuthority(config, closeDuel(40));
    let bundle: AuthorityBundle | undefined;
    for (let frame = 1; frame <= 90; frame++) bundle = authority.step() ?? bundle;
    session.receiveBundle(authority.snapshotBundle(), edge(90));
    tick(at(90 + RESYNC_FRAMES), 0);
    expect(session.frame).toBe(90 + RESYNC_FRAMES);
    expect(session.stats.resyncs).toBe(1);
    expect(bundle).toBeDefined();
    // It restarted from the server's state, not its own.
    expect(session.rollback.confirmedFrame).toBe(90);
    expect(session.confirmedState).toEqual(authority.state);
    expect(session.stats.desyncs).toBe(0);
  });

  it("resyncs to the server's state when its ticks stall while contiguous bundles keep arriving (a hidden tab)", () => {
    const initial = closeDuel(100);
    const { session, sent, at, edge, tick } = sessionRig({ initial, delay: 3 });
    const authority = new DuelAuthority(config, initial);
    const serverStates = new Map<number, DuelState>([[0, initial]]);
    session.receiveBundle(authority.snapshotBundle(), edge(0));
    // Player one walks right the whole time; player two walks left from frame 20 to 80. The tab is hidden from frame
    // 31 to 120: its timers do not run, but every bundle still arrives, in order and without a gap.
    const hidden = (frame: number) => frame > 30 && frame <= 120;
    const step = (frame: number) => {
      if (!hidden(frame)) tick(at(frame), R);
      for (const message of sent.splice(0)) authority.receive(0, message.frame, message.inputs);
      authority.receive(1, frame, [frame >= 20 && frame < 80 ? L : 0]);
      const bundle = authority.step();
      serverStates.set(frame, authority.state);
      if (bundle !== undefined) session.receiveBundle(bundle, edge(frame + 1));
    };
    for (let frame = 1; frame <= 120; frame++) step(frame);
    expect(session.frame).toBe(30);
    expect(session.rollback.receivedFrame).toBe(120);
    expect(session.stats.resyncs).toBe(0);

    // The first tick after the stall is far behind the server: it restarts from the latest snapshot (frame 120) instead
    // of catching up four frames at a time, and its confirmed state is the server's.
    tick(at(121), R);
    expect(session.stats.resyncs).toBe(1);
    // (The bundles arrive a frame after they leave, so the clock puts the server a frame back from the tick's own.)
    expect(session.frame).toBe(120);
    expect(session.rollback.confirmedFrame).toBe(120);
    expect(session.confirmedState).toEqual(serverStates.get(120));
    // During the stall the server held player one's walk for 250 ms and then substituted neutral; the client uses
    // what the server applied, not what it would have sent.
    expect(session.confirmedState.fighters[0].x).toBe(serverStates.get(120)!.fighters[0].x);
    expect(authority.stats.neutral[0]).toBeGreaterThan(0);

    for (let frame = 121; frame <= 180; frame++) step(frame);
    tick(at(181), R);
    expect(session.rollback.confirmedFrame).toBe(180);
    expect(session.confirmedState).toEqual(serverStates.get(180));
    expect(session.stats).toMatchObject({ desyncs: 0, resyncs: 1 });
    expect(session.stats.hashChecks).toBeGreaterThanOrEqual(20);
  });

  it("after the result steps only to the final bundle's frame, so it ends on the KO and never passes it", () => {
    const initial = nearKo(40);
    const { session, sent, at, edge, tick } = sessionRig({ initial, delay: 3 });
    const authority = new DuelAuthority(config, initial);
    // The player taps J at frame 2. The client's timer then falls behind (a busy main thread) while the server steps
    // on to the KO and its bundles arrive; the room's result follows them.
    for (let frame = 1; !authority.over; frame++) {
      if (frame <= 6) tick(at(frame), frame === 2 ? J : 0);
      for (const message of sent.splice(0)) authority.receive(0, message.frame, message.inputs);
      const bundle = authority.step();
      if (bundle !== undefined) session.receiveBundle(bundle, edge(frame + 1));
    }
    const koFrame = authority.frame;
    expect(authority.state.result).toMatchObject({ winner: 0, reason: "ko", frame: koFrame });
    expect(session.rollback.receivedFrame).toBe(koFrame);
    // Where the HUD stood when the result came: short of the KO.
    expect(session.rollback.confirmedFrame).toBeLessThan(koFrame);

    session.finish();
    expect(session.frame).toBe(6);
    expect(session.rollback.frame).toBe(koFrame);
    expect(session.rollback.confirmedFrame).toBe(koFrame);
    expect(session.confirmedState).toEqual(authority.state);
    expect(session.confirmedState.result).toMatchObject({ winner: 0, reason: "ko" });
    // Nothing moves it past the end: not another finish, nor a tick far ahead.
    session.finish();
    tick(at(koFrame + 60), 0);
    expect(session.rollback.frame).toBe(koFrame);
    expect(session.state.frame).toBe(koFrame);
    expect(session.stats.desyncs).toBe(0);
  });

  it("sends one message every second frame, and never more than 30 in a second when its clock races ahead", () => {
    const steady = sessionRig();
    for (let frame = 0; frame < 240; frame++) steady.tick(steady.at(frame), R);
    expect(steady.sent).toHaveLength(steady.session.stats.messages);
    expect(steady.sent.length).toBeGreaterThanOrEqual(118);
    expect(steady.session.stats.throttledSends).toBe(0);

    // Messages keep arriving stamped ten frames further ahead than before: the clock keeps catching up.
    const racing = sessionRig();
    for (let step = 0; step < 1500; step++) {
      const now = racing.edge(0) + step * 4;
      if (step % 50 === 0) racing.session.receiveProbe({ frame: Math.floor((now - 1000) / FRAME_MS) + (step / 50) * 10, rtt: 0 }, now);
      racing.tick(now, R);
    }
    expect(racing.session.stats.throttledSends).toBeGreaterThan(0);
    for (const [index, time] of racing.sentAt.entries()) {
      expect(racing.sentAt.filter((other, otherIndex) => otherIndex >= index && other < time + 1000).length).toBeLessThanOrEqual(MESSAGES_PER_SECOND);
    }
  });
});

