6	
7	const { moveset } = defaultDuelConfig;
8	const SUB = moveset.arena.subPixelsPerPixel;
9	export const ARENA_WIDTH = moveset.arena.width / SUB;
10	export const ARENA_HEIGHT = 320;
11	/** The floor's height on the canvas, in pixels from the top. */
12	const FLOOR = ARENA_HEIGHT - 40;
13	
14	export const FIGHTER_COLORS = [0xf4b942, 0x3dd6d0] as const;
15	const BACKGROUND = 0x1b2a38;
16	const FLOOR_COLOR = 0x3b5266;
17	const HURTBOX_COLOR = 0x46e06b;
18	const HITBOX_COLOR = 0xff3b30;
19	const PUSHBOX_COLOR = 0x6aa9ff;
20	
21	/** What the arena draws from: the client's predicted duel, its fresh events, and the view options. */
22	export interface ArenaSource {
23	  /** The predicted state to draw, or undefined before the duel exists. */
24	  state(): DuelState | undefined;
25	  /** Events of newly simulated frames, each once (stable ids). */
26	  drainEvents(): DuelFeedEvent[];
27	  /** The predicted state of an earlier frame, while the client still holds it. */
28	  stateAt(frame: number): DuelState | undefined;
29	  /** The developer toggle: draw hurtboxes, pushboxes and active hitboxes. */
30	  showBoxes(): boolean;
31	  /** Big centred text: the countdown, or the result. */
32	  banner(): string;
33	}
34	
35	/** A fighter as drawn this frame, for the DOM report the browser tests read. */
36	export interface DrawnFighter {
37	  readonly x: number;
38	  readonly y: number;
39	  readonly action: string;
40	  readonly moveId: string | null;
41	  readonly facing: number;
42	  readonly health: number;
43	}
44	
45	/** Arena pixels of a box in sub-pixels (y up from the floor). */
46	function toCanvas(box: WorldBox): { x: number; y: number; w: number; h: number } {
47	  return { x: box.x0 / SUB, y: FLOOR - box.y1 / SUB, w: (box.x1 - box.x0) / SUB, h: (box.y1 - box.y0) / SUB };
48	}
49	
50	function stance(fighter: FighterState): "standing" | "crouching" | "airborne" {
51	  if (fighter.y > 0 || fighter.vy > 0 || fighter.action === "jump") return "airborne";
52	  return fighter.crouching ? "crouching" : "standing";
53	}
54	
55	/** The fighter's active hitbox this frame, if its move is on an active frame. */
56	function activeHitbox(fighter: FighterState): WorldBox | undefined {
57	  if (fighter.action !== "attack" || fighter.moveId === null) return undefined;
58	  const move = findMove(moveset, fighter.moveId);
59	  const frame = fighter.actionFrame;
60	  const active = typeof move.timing.active === "number" ? move.timing.active : 0;
61	  if (frame <= move.timing.startup || frame > move.timing.startup + active) return undefined;
62	  return worldBox(move.hitbox, fighter.x, fighter.y, fighter.facing);
63	}
64	
65	/** The outline colour that tells the fighter's state at a glance. */
66	function stateColor(fighter: FighterState): number {
67	  switch (fighter.action) {
68	    case "hitstun":
69	    case "knockdown":
70	      return 0xff5a4f;
71	    case "blockstun":
72	      return 0xffffff;
73	    case "stagger":
74	      return 0xff9f1c;
75	    case "thrown":
76	    case "throw-break":
77	      return 0xc77dff;
78	    case "attack":
79	      return activeHitbox(fighter) === undefined ? 0xfff3b0 : 0xff3b30;
80	    default:
81	      return 0x0b1620;
82	  }
83	}
