86	  if (fighter.action === "attack" && fighter.moveId !== null) {
87	    const move = findMove(moveset, fighter.moveId);
88	    return `${move.timing.name} ${fighter.actionFrame}`;
89	  }
90	  return fighter.crouching && fighter.action !== "crouch" ? `${fighter.action} (low)` : fighter.action;
91	}
